type: object
additionalProperties: false
required: [version_schema, id, date_documentation, pays, devise, unite_taux, horizons_analyse_ans, nature, description, dependances, conventions, calcul, categories, rattachement, sources]
properties:
  version_schema: {const: 1}
  id: {const: inflation-france}
  date_documentation: {type: string, pattern: '^\d{4}-\d{2}-\d{2}$'}
  pays: {const: FR}
  devise: {const: EUR}
  unite_taux: {const: pourcentage_annuel}
  horizons_analyse_ans: {const: [10, 15]}
  nature: {const: scenarios_de_cadrage}
  description: {$ref: '#/$defs/texte'}
  dependances:
    type: object
    additionalProperties: false
    required: [schema, stacks, utilisation]
    properties:
      schema: {const: source/schema-inflation.yaml}
      stacks: {$ref: '#/$defs/textes'}
      utilisation: {$ref: '#/$defs/texte'}
  conventions: {$ref: '#/$defs/textes'}
  calcul:
    type: object
    additionalProperties: false
    required: [formule_prix, definition_n, formule_facteur, formule_variation_pct, application, priorite]
    properties:
      formule_prix: {$ref: '#/$defs/texte'}
      definition_n: {$ref: '#/$defs/texte'}
      formule_facteur: {$ref: '#/$defs/texte'}
      formule_variation_pct: {$ref: '#/$defs/texte'}
      application: {$ref: '#/$defs/texte'}
      priorite: {$ref: '#/$defs/texte'}
  categories:
    type: object
    additionalProperties: false
    required: [licences_logiciels, tjm_ingenierie, cloud]
    properties:
      licences_logiciels: {$ref: '#/$defs/categorie'}
      tjm_ingenierie: {$ref: '#/$defs/categorie'}
      cloud: {$ref: '#/$defs/categorie'}
  rattachement:
    type: object
    additionalProperties: false
    required: [prestations, regles, hors_taux_autonome]
    properties:
      prestations:
        type: object
        additionalProperties: false
        required: [developpement, integration, support_n3, support_n1]
        properties:
          developpement: {const: tjm_ingenierie}
          integration: {const: tjm_ingenierie}
          support_n3: {const: tjm_ingenierie}
          support_n1: {const: tjm_ingenierie}
      regles: {$ref: '#/$defs/textes'}
      hors_taux_autonome: {$ref: '#/$defs/textes'}
  sources:
    type: object
    minProperties: 1
    additionalProperties: {$ref: '#/$defs/source'}
$defs:
  texte: {type: string, minLength: 1}
  textes:
    type: array
    minItems: 1
    uniqueItems: true
    items: {$ref: '#/$defs/texte'}
  categorie:
    type: object
    additionalProperties: false
    required: [libelle, assiette, taux_annuel_pct, fondement, niveau_etayage, justification, sensibilite, limites, sources]
    properties:
      libelle: {$ref: '#/$defs/texte'}
      assiette: {$ref: '#/$defs/texte'}
      taux_annuel_pct:
        type: object
        additionalProperties: false
        required: [bas, central, haut]
        properties:
          bas: {type: number, exclusiveMinimum: -100}
          central: {type: number, exclusiveMinimum: -100}
          haut: {type: number, exclusiveMinimum: -100}
      fondement: {const: hypothese_analyste}
      niveau_etayage: {enum: [faible, intermediaire, fort]}
      justification: {$ref: '#/$defs/texte'}
      sensibilite: {$ref: '#/$defs/texte'}
      limites: {$ref: '#/$defs/texte'}
      sources: {$ref: '#/$defs/textes'}
  source:
    type: object
    additionalProperties: false
    required: [titre, url, nature, portee, repere, observations, limite]
    properties:
      titre: {$ref: '#/$defs/texte'}
      url: {type: string, pattern: '^https://'}
      nature: {enum: [enquete_previsions, indice_historique, annonce_editeur, annonce_fournisseur]}
      portee: {$ref: '#/$defs/texte'}
      repere: {$ref: '#/$defs/texte'}
      observations: {$ref: '#/$defs/textes'}
      limite: {$ref: '#/$defs/texte'}

