tools/business_map.py.text:
"""A derived, versioned business reading: no economic formulas or editable hierarchy."""
from copy import deepcopy
import hashlib
from urllib.parse import urlencode
from jsonschema import Draft202012Validator
from validate_stacks import ROOT, read

PATH = 'source/lecture-metier.yaml'


def validate(spec=None, scope=None):
    spec = spec if spec is not None else read(ROOT / PATH)
    Draft202012Validator(read(ROOT / 'source/schema-lecture-metier.yaml')).validate(spec)
    snapshot = read(ROOT / spec['cartographie'])
    assert hashlib.sha256((ROOT / spec['cartographie']).read_bytes()).hexdigest() == spec['empreinte']
    assert snapshot['domaine_id'] == spec['domaine']
    nodes = {n['id']: n for n in snapshot['nodes']}
    caps = {i for i, n in nodes.items() if n['kind'] == 'capability'}
    neighbors = read(ROOT / spec['frontieres_source'])
    assert neighbors['provenance']['sha256'] == snapshot['provenance']['sha256']
    assert hashlib.sha256((ROOT / spec['frontieres_source']).read_bytes()).hexdigest() == spec['frontieres_empreinte']
    external = {n['id']: n for n in neighbors['nodes']}
    assert len(external) == len(neighbors['nodes']) and not external.keys() & nodes.keys()
    scope = scope if scope is not None else read(ROOT / 'source/explications-modele.yaml')['perimetre_compare']
    assert len({r['id'] for r in scope}) == len(scope)
    assert {t['id'] for t in spec['sujets']} == {r['id'] for r in scope}
    assert len(spec['sujets']) == len(scope)
    for theme in spec['sujets']:
        assert set(theme['capacites']) <= caps
        assert set(theme['ancrages']) <= {i for i,n in nodes.items() if n['kind'] in ('domain','area','business_area')}
        assert set(theme['voisins']) <= external.keys()
        assert theme['capacites'] or theme['ancrages'] or theme['voisins'] or theme['nature'] == 'technique'
    return spec, snapshot, external


def build(complexity, business, buy, integration, scope):
    spec, snapshot, external = validate(scope=scope)
    names = {r['id']: r for r in scope}
    nodes = {n['id']: n for n in snapshot['nodes']}
    rows = deepcopy(complexity['rows'])
    assert {r['capacite_id'] for r in rows} == {i for i,n in nodes.items() if n['kind']=='capability'}
    work = {r['id']: r for r in business['rows']}
    reviews = {(r['capacite'],r['stack']): r for r in buy['revues']}
    exceptions = {e['id']: e for e in buy['exceptions']}

    def proofs(ids, registry):
        assert set(ids) <= registry.keys(), ('Missing evidence', set(ids)-registry.keys())
        return [dict(id=i, **registry[i]) for i in ids]

    themes = []
    for t in spec['sujets']:
        selected = set(t['capacites']) | {r['capacite_id'] for r in rows if set(r['chemin']) & set(t['ancrages'])}
        themes.append(dict(id=t['id'], title=names[t['id']]['fonction'], kind=t['nature'],
            capabilities=[r['capacite_id'] for r in rows if r['capacite_id'] in selected], anchors=t['ancrages'],
            neighbors=[dict(id=i,nom=external[i]['fields']['name'],kind=external[i]['kind']) for i in t['voisins']],
            content=names[t['id']], rationale=t['justification'], source=t['source'], status=t['statut']))

    funding = []
    for w in business['rows']:
        for slug, a in w['stacks'].items():
            a['proofs'] = proofs(a['coverage']['sources'], business['sources'])
            # The instance is (work owner, option); a reusable estimate template is not a funding identity.
            a['funding_id'] = w['id'] + ':' + slug
            funding.append(dict(id=a['funding_id'], owner=w['capacite_id'], block=w['id'], stack=slug,
                template=a['travaux_ref'], valuation=a['valuation'],
                beneficiaries=[r['capacite_id'] for r in business['rows'] if any(x['proprietaire']==w['id'] for x in r['reuse'])]))
    assert len({f['id'] for f in funding}) == len(funding)
    for r in rows:
        cid = r['capacite_id']
        r['work'] = work[r['id']]
        r['buy'] = {}
        for slug in ('microsoft','sap'):
            review = deepcopy(reviews[cid,slug])
            review['proofs'] = proofs(review['coverage']['sources'], buy['coverage_sources'])
            review['exceptions'] = [dict(**exceptions[e],proofs=proofs(exceptions[e]['sources'],buy['sources'])) for e in review['exceptions']]
            r['buy'][slug] = review
        r['themes'] = [t['id'] for t in themes if cid in t['capabilities']]
        r['scenarios'] = [dict(id=s['scenario'],title=s['source']['title'],
            route='#estimations?'+urlencode(dict(section='integration',focus='scenario-'+s['scenario'])))
            for s in integration['scenarios'] if cid in s['capacites']]
    return dict(source=dict(path=spec['cartographie'],date=snapshot['date_capture'],
        version=snapshot['provenance']['version'],revision=snapshot['provenance']['sha256'],
        domain=dict(id=spec['domaine'],nom=nodes[spec['domaine']]['fields']['name'])),
        rows=rows,themes=themes,transverse=work['TRANSVERSE'],funding=funding)

tools/buy_qualification.py.text:
"""Validate product coverage separately from Make work and contextual integration."""
import hashlib
from jsonschema import Draft202012Validator
from validate_stacks import ROOT, read

PATH='source/qualification-buy.yaml'

def coverage_sources(model):
    """Resolve the evidence registry shared by Make and Buy coverage profiles."""
    sources=read(ROOT/'sources/core-system-solutions-2026-10-22.yaml')['sources']
    for key,source in model.get('preuves',{}).items():
        assert key not in sources or sources[key]==source, ('Conflicting coverage source',key)
        sources[key]=source
    return sources

def validate(model, doc=None):
    d=doc if doc is not None else read(ROOT/PATH)
    Draft202012Validator(read(ROOT/'source/schema-qualification-buy.yaml')).validate(d)
    blocks={b['bloc']:b['capacite'] for b in model['blocs']}
    assert len(blocks)==len(model['blocs']) and len(set(blocks.values()))==len(blocks), 'Duplicate capability identity'
    blocks['TRANSVERSE']=None
    expected={(cap,s) for cap in blocks.values() for s in ('microsoft','sap')}
    assert {(r['capacite'],r['stack']) for r in d['revues']}==expected, 'Buy capability coverage'
    assert len(d['revues'])==len(expected)
    sources=coverage_sources(model)
    exceptions={e['id']:e for e in d['exceptions']}
    assert len(exceptions)==len(d['exceptions'])
    for e in exceptions.values():
        assert set(e['blocs'])<=blocks.keys() and set(e['sources'])<=d['sources'].keys()
        if e['statut']=='a_qualifier':
            assert e['cout_initial_eur_ht'] is None and e['cout_annuel_eur_ht'] is None
    components={s:{c['id'] for c in read(ROOT/f'source/stacks/{s}.yaml')['elements']} for s in ('microsoft','sap')}
    for row in d['revues']:
        assert row['bloc'] in blocks and row['capacite']==blocks[row['bloc']], 'Buy capability alias'
        coverage=model['couvertures'][row['couverture_ref']]
        assert set(coverage['composants'])<=components[row['stack']]
        assert set(coverage['sources'])<=sources.keys(), ('Unknown Buy coverage source',row['couverture_ref'])
        for key in coverage['sources']:
            source=sources[key]
            assert all(isinstance(source.get(field),str) and source[field].strip() for field in ('titre','reference','portee')), ('Incomplete coverage source',key)
        targets={e['id'] for e in exceptions.values() if row['stack'] in e['stacks'] and row['bloc'] in e['blocs']}
        assert set(row['exceptions'])==targets
        assert (row['statut']=='point_cible')==bool(targets)
    ids=set()
    for work in d['developpements']:
        assert work['id'] not in ids;ids.add(work['id'])
        e=exceptions[work['exception']]
        assert e['statut']=='ecart_demontre' and work['stack'] in e['stacks']
        assert work['preuve'] in d['sources'] and work['fonction_absente'] and work['financement_distinct']
        assert all(0<=lo<=mid<=hi for lo,mid,hi in zip(work['bas'],work['central'],work['haut']))
    return d

def integration_paths():
    d=read(ROOT/'source/parcours-integration.yaml')
    assert hashlib.sha256((ROOT/d['capture']).read_bytes()).hexdigest()==d['empreinte']
    catalog=read(ROOT/d['capture'])['scenario_catalog']
    scenarios={s['id']:s for s in catalog['scenarios']};paths={p['id']:p for p in catalog['paths']}
    assert len(scenarios)==len(catalog['scenarios']) and len(paths)==len(catalog['paths'])
    assert len(d['scenarios'])==len(scenarios) and {s['scenario'] for s in d['scenarios']}==scenarios.keys()
    caps={b['capacite_id'] for b in read(ROOT/'source/grille-complexite.yaml')['blocs']}
    activities={a['id'] for a in read(ROOT/'source/integration.yaml')['activites']}
    lots={l['id']:l for l in d['lots']}
    assert len(lots)==len(d['lots'])
    assert {i for l in lots.values() for i in l['activites']}==activities
    assert sum(len(l['activites']) for l in lots.values())==len(activities)
    for row in d['scenarios']:
        assert set(row)=={'scenario','parcours','capacites','lots','statut','justification'}
        assert set(row['lots'])<=lots.keys() and len(row['lots'])==len(set(row['lots']))
        linked={p['id'] for p in paths.values() if p['scenario_id']==row['scenario']}
        assert set(row['parcours'])==linked
        contributions={c['node_id'] for pid in linked for step in paths[pid]['steps'] for c in step['contributions'] if c['node_id'] in caps}
        assert set(row['capacites'])==contributions
    return d,catalog

